'use strict';
/**
 * NYXA Unified Room — persistence layer.
 *
 * Provenance: generated by Claude Code (Anthropic) for Johannes Süß, 2026-11-07 (Europe/Berlin).
 * Status: DRAFT — REFERENCE IMPLEMENTATION — NOT DEPLOYED.
 *
 * Zero-dependency: uses node:sqlite (Node >= 22.13). Server B runs Node v22.23.3 (verified 2026-11-07).
 * One SQLite file is the authoritative server-side state for messages, tasks, approvals,
 * effects and audit. WAL + busy_timeout allow several worker processes on one host.
 */
const { DatabaseSync } = require('node:sqlite');
const crypto = require('node:crypto');

const SCHEMA = `
CREATE TABLE IF NOT EXISTS contents (
  content_ref TEXT PRIMARY KEY,
  byte_length INTEGER NOT NULL,
  char_length INTEGER NOT NULL,
  text        TEXT NOT NULL,
  created_at  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS messages (
  seq             INTEGER PRIMARY KEY AUTOINCREMENT,
  message_id      TEXT NOT NULL UNIQUE,
  conversation_id TEXT NOT NULL,
  session_id      TEXT,
  actor_id        TEXT NOT NULL,
  actor_kind      TEXT NOT NULL,
  channel         TEXT NOT NULL CHECK (channel IN ('text','voice','agent','mail','system')),
  timestamp       TEXT NOT NULL,
  content_ref     TEXT NOT NULL REFERENCES contents(content_ref),
  delivery_status TEXT NOT NULL,
  visibility      TEXT NOT NULL,
  provenance      TEXT NOT NULL,
  correlation_id  TEXT,
  trust           TEXT NOT NULL DEFAULT 'trusted_principal'
);
CREATE INDEX IF NOT EXISTS idx_messages_conv ON messages(conversation_id, seq);
CREATE TABLE IF NOT EXISTS deliveries (
  message_id  TEXT NOT NULL,
  session_id  TEXT NOT NULL,
  status      TEXT NOT NULL CHECK (status IN ('PENDING','DELIVERED','ACKED','FAILED')),
  attempts    INTEGER NOT NULL DEFAULT 0,
  updated_at  TEXT NOT NULL,
  PRIMARY KEY (message_id, session_id)
);
CREATE TABLE IF NOT EXISTS sessions (
  session_id      TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL,
  principal_id    TEXT NOT NULL,
  channel         TEXT NOT NULL,
  last_acked_seq  INTEGER NOT NULL DEFAULT 0,
  opened_at       TEXT NOT NULL,
  closed_at       TEXT
);
CREATE TABLE IF NOT EXISTS tasks (
  task_id           TEXT PRIMARY KEY,
  created_by        TEXT NOT NULL,
  requested_by      TEXT NOT NULL,
  executor          TEXT NOT NULL,
  task_type         TEXT NOT NULL,
  scope             TEXT NOT NULL,
  scope_hash        TEXT NOT NULL,
  context_refs      TEXT NOT NULL,
  instruction_ref   TEXT,
  execution_mode    TEXT NOT NULL,
  approval_required INTEGER NOT NULL,
  approval_status   TEXT NOT NULL,
  status            TEXT NOT NULL,
  idempotency_key   TEXT NOT NULL UNIQUE,
  conversation_id   TEXT,
  correlation_id    TEXT NOT NULL,
  verification      TEXT NOT NULL DEFAULT 'required',
  attempts          INTEGER NOT NULL DEFAULT 0,
  max_attempts      INTEGER NOT NULL DEFAULT 3,
  not_before        TEXT,
  expires_at        TEXT,
  lease_owner       TEXT,
  lease_token       TEXT,
  lease_expires_at  TEXT,
  heartbeat_at      TEXT,
  cost_budget_cents INTEGER NOT NULL DEFAULT 0,
  cost_spent_cents  INTEGER NOT NULL DEFAULT 0,
  result_ref        TEXT,
  result_provenance TEXT,
  error             TEXT,
  dead_letter       INTEGER NOT NULL DEFAULT 0,
  version           INTEGER NOT NULL DEFAULT 0,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_tasks_claim ON tasks(executor, status, not_before, created_at);
CREATE TABLE IF NOT EXISTS approvals (
  approval_id TEXT PRIMARY KEY,
  task_id     TEXT NOT NULL REFERENCES tasks(task_id),
  decision    TEXT NOT NULL CHECK (decision IN ('APPROVED','DENIED')),
  decided_by  TEXT NOT NULL,
  basis       TEXT NOT NULL,
  scope_hash  TEXT NOT NULL,
  decided_at  TEXT NOT NULL,
  revoked_at  TEXT,
  revoked_by  TEXT
);
CREATE TABLE IF NOT EXISTS mandates (
  mandate_id     TEXT PRIMARY KEY,
  granted_by     TEXT NOT NULL,
  executor       TEXT NOT NULL,
  task_types     TEXT NOT NULL,
  operations     TEXT NOT NULL,
  max_cost_cents INTEGER NOT NULL,
  valid_until    TEXT NOT NULL,
  revoked_at     TEXT,
  created_at     TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS effects (
  effect_key  TEXT PRIMARY KEY,
  task_id     TEXT NOT NULL,
  operation   TEXT NOT NULL,
  resource    TEXT NOT NULL,
  status      TEXT NOT NULL CHECK (status IN ('STARTED','CONFIRMED','FAILED','UNKNOWN')),
  evidence    TEXT,
  started_at  TEXT NOT NULL,
  finished_at TEXT
);
CREATE TABLE IF NOT EXISTS executor_config (
  executor              TEXT PRIMARY KEY,
  mode                  TEXT NOT NULL CHECK (mode IN ('DIRECT','ON_APPROVAL','HOURLY','DAILY','MANUAL','PAUSED')),
  interval_minutes      INTEGER NOT NULL DEFAULT 60,
  daily_time            TEXT NOT NULL DEFAULT '07:00',
  timezone              TEXT NOT NULL DEFAULT 'Europe/Berlin',
  allowed_task_types    TEXT NOT NULL,
  allowed_operations    TEXT NOT NULL,
  daily_budget_cents    INTEGER NOT NULL DEFAULT 0,
  max_parallel          INTEGER NOT NULL DEFAULT 1,
  verification_policy   TEXT NOT NULL DEFAULT 'required',
  updated_by            TEXT NOT NULL,
  updated_at            TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS audit (
  seq            INTEGER PRIMARY KEY AUTOINCREMENT,
  at             TEXT NOT NULL,
  actor          TEXT NOT NULL,
  action         TEXT NOT NULL,
  subject        TEXT NOT NULL,
  decision       TEXT,
  from_status    TEXT,
  to_status      TEXT,
  correlation_id TEXT,
  detail         TEXT
);
CREATE INDEX IF NOT EXISTS idx_audit_corr ON audit(correlation_id, seq);
CREATE TABLE IF NOT EXISTS scheduler_ticks (
  executor   TEXT PRIMARY KEY,
  last_tick  TEXT NOT NULL,
  worker_id  TEXT NOT NULL
);
`;

function open(file = ':memory:') {
  const db = new DatabaseSync(file);
  db.exec('PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000; PRAGMA foreign_keys = ON;');
  db.exec(SCHEMA);
  return db;
}

/** Runs fn inside BEGIN IMMEDIATE so concurrent writers (other processes) are serialized. */
function tx(db, fn) {
  db.exec('BEGIN IMMEDIATE');
  try {
    const out = fn();
    db.exec('COMMIT');
    return out;
  } catch (e) {
    try { db.exec('ROLLBACK'); } catch { /* already rolled back */ }
    throw e;
  }
}

/** Canonical JSON (sorted keys) so hashes are stable across processes. */
function canonical(value) {
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (value && typeof value === 'object') {
    return '{' + Object.keys(value).sort().map(k => JSON.stringify(k) + ':' + canonical(value[k])).join(',') + '}';
  }
  return JSON.stringify(value === undefined ? null : value);
}

const sha256 = s => crypto.createHash('sha256').update(s).digest('hex');
const uuid = () => crypto.randomUUID();

function audit(db, { at, actor, action, subject, decision = null, from = null, to = null, correlation_id = null, detail = null }) {
  db.prepare(`INSERT INTO audit (at, actor, action, subject, decision, from_status, to_status, correlation_id, detail)
              VALUES (?,?,?,?,?,?,?,?,?)`)
    .run(at, actor, action, subject, decision, from, to, correlation_id, detail == null ? null : canonical(detail));
}

module.exports = { open, tx, canonical, sha256, uuid, audit };
